using Microsoft.EntityFrameworkCore;
using PeopleHub.Infrastructure.Persistence;
using PeopleHub.Application.Common;
using PeopleHub.Application.Modules.Benefits;
using PeopleHub.Domain.Entities;
namespace PeopleHub.Tests;
public class BenefitTests
{
 class User(int emp=1,bool grant=true):ICurrentUser{public string Email=>"benefit@example.local";public int? EmployeeId=>emp;public int UserId=>emp;public bool IsAuthenticated=>true;public bool IsInRole(string r)=>false;public bool Can(string p)=>p==Perm.BenefitsManage&&grant;}
 class Time:TimeProvider{public override DateTimeOffset GetUtcNow()=>new(2026,11,24,18,0,0,TimeSpan.Zero);}
 static async Task<AppDbContext> Db(){var d=new AppDbContext(new DbContextOptionsBuilder<AppDbContext>().UseSqlite("Data Source=:memory:").Options);await d.Database.OpenConnectionAsync();await d.Database.MigrateAsync();await SeedData.InitializeAsync(d,"Admin123!","Demo123!",new DateTime(2026,11,24));return d;}
 static BenefitService S(AppDbContext d,User? u=null){u??=new();var c=new AppClock(new Time());return new(d,u,c,new AuditService(d,u,c));}
 static async Task<int> Plan(AppDbContext d,bool dependents=true){await S(d).AddPlanAsync("Fictional medical plan","Fictional provider","Reviewed eligibility evidence required","Fictional coverage, no real insurance",dependents,500,100,"EGP");return await d.Set<BenefitPlan>().Select(x=>x.Id).SingleAsync();}
 static Task Enroll(AppDbContext d,int plan,int? dependent=null)=>S(d).EnrollAsync(plan,6,dependent,new(2026,12,1),new(2027,11,30),"Reviewed fictional eligibility REF-47","DEMO-OPS");
 [Fact]public async Task RecordsStaySeparateFromPayrollAndPrivateToOwnerAndGrant(){await using var d=await Db();int plan=await Plan(d);var lines=await d.Set<PayrollLine>().CountAsync();await Enroll(d,plan);Assert.Single((await S(d,new(6,false)).GetAsync()).Enrollments);Assert.Empty((await S(d,new(7,false)).GetAsync()).Enrollments);Assert.Single((await S(d).GetAsync()).Enrollments);Assert.Equal(lines,await d.Set<PayrollLine>().CountAsync());await Assert.ThrowsAsync<DomainException>(()=>S(d,new(6,false)).EnrollAsync(plan,6,null,new(2026,12,1),new(2027,1,1),"Evidence","OPS"));}
 [Fact]public async Task DependentMustBelongToEmployeeAndPlanPermitCoverage(){await using var d=await Db();int plan=await Plan(d,false);var dep=new EmployeeDependent{EmployeeId=6,Name="Fictional child",Relationship="Child"};d.Add(dep);await d.SaveAsync();await Assert.ThrowsAsync<DomainException>(()=>Enroll(d,plan,dep.Id));var p=await d.Set<BenefitPlan>().FindAsync(plan);Assert.False(p!.DependentsAllowed);d.Add(new BenefitPlan{Name="Fictional dependent plan",Provider="Demo",Eligibility="Recorded evidence",Coverage="Demo",DependentsAllowed=true,Currency="EGP"});await d.SaveAsync();int other=await d.Set<BenefitPlan>().Where(x=>x.Id!=plan).Select(x=>x.Id).SingleAsync();await S(d).EnrollAsync(other,6,dep.Id,new(2026,12,1),new(2027,11,30),"Evidence","OPS");Assert.Equal(dep.Name,(await d.Set<BenefitEnrollment>().SingleAsync()).CoveredName);var wrong=new EmployeeDependent{EmployeeId=7,Name="Other child",Relationship="Child"};d.Add(wrong);await d.SaveAsync();await Assert.ThrowsAsync<DomainException>(()=>Enroll(d,other,wrong.Id));}
 [Fact]public async Task OverlapCancellationAndReenrolmentRespectRecordedDates(){await using var d=await Db();int plan=await Plan(d);await Enroll(d,plan);await Assert.ThrowsAsync<DomainException>(()=>Enroll(d,plan));var e=await d.Set<BenefitEnrollment>().SingleAsync();await Assert.ThrowsAsync<DomainException>(()=>S(d).CancelAsync(e.Id,new(2026,12,15),""));await S(d).CancelAsync(e.Id,new(2026,12,15),"Fictional cancellation evidence");await Assert.ThrowsAsync<DomainException>(()=>S(d).CancelAsync(e.Id,new(2026,12,20),"repeat"));await Assert.ThrowsAsync<DomainException>(()=>S(d).EnrollAsync(plan,6,null,new(2026,12,14),new(2027,1,1),"Evidence","OPS"));await S(d).EnrollAsync(plan,6,null,new(2026,12,15),new(2027,1,1),"New evidence","OPS2");Assert.Equal(2,await d.Set<BenefitEnrollment>().CountAsync());}
 [Theory][InlineData("plan")][InlineData("enrolment")][InlineData("cancellation")]public async Task BenefitEvidenceIsAppendOnly(string kind){await using var d=await Db();int plan=await Plan(d);await Enroll(d,plan);var e=await d.Set<BenefitEnrollment>().SingleAsync();await S(d).CancelAsync(e.Id,new(2026,12,1),"Demo");if(kind=="plan")(await d.Set<BenefitPlan>().SingleAsync()).EmployerMonthly=1;else if(kind=="enrolment")(await d.Set<BenefitEnrollment>().SingleAsync()).CostCenter="Overwrite";else (await d.Set<BenefitCancellation>().SingleAsync()).Reason="Overwrite";await Assert.ThrowsAsync<InvalidOperationException>(()=>d.SaveAsync());}
 [Fact]public async Task PlanInputsAndEligibilityEvidenceAreRequired(){await using var d=await Db();await Assert.ThrowsAsync<DomainException>(()=>S(d,new(6,false)).AddPlanAsync("Demo","Demo","Rules","Coverage",false,0,0,"EGP"));await Assert.ThrowsAsync<DomainException>(()=>S(d).AddPlanAsync("Demo","Demo","","Coverage",false,0,0,"EGP"));int plan=await Plan(d);await Assert.ThrowsAsync<DomainException>(()=>S(d).EnrollAsync(plan,6,null,new(2026,12,1),new(2027,1,1),"","OPS"));await Assert.ThrowsAsync<DomainException>(()=>S(d).EnrollAsync(plan,6,null,new(2026,11,1),new(2027,1,1),"Evidence","OPS"));Assert.Empty(await d.Set<BenefitEnrollment>().ToListAsync());}
}
